<?php
/** Proof — the reminders (activities-calendar.md §4) with the worker run by hand (CRM_WORKER_NOW): a due reminder delivered once (the bell, the email
 * outbox row, reminded_at), not before its time, a snooze re-delivers, a done one never; a text when the person asked; an agent's as a dispatch;
 * recurring tasks expanded one ahead; the next step mended. */
require __DIR__ . '/lib.php';
$x = run_tag();
$d = deal_make(26);
pg_run("DELETE FROM notification_prefs WHERE member_id = 26");
echo "1. Delivered once, at its time\n";
$a = act_id(26, ['kind' => 'call', 'subject' => "Remind $x", 'deal' => $d, 'starts_at' => at('+1 hour'), 'remind_minutes_before' => 30]);
$remAt = act_row($a)['remind_at'];
$w = worker_at('reminders', gmdate(DATE_ATOM, strtotime('+10 minutes')));
ok(act_row($a)['reminded_at'] === null && (int) one("SELECT count(*) FROM notifications WHERE activity_id = :a", ['a' => $a]) === 0, 'before its time (10 minutes on, the reminder is at 30 before): nothing');
$since = last_activity_id();
$w = worker_at('reminders', gmdate(DATE_ATOM, strtotime('+31 minutes')));
$n = q("SELECT * FROM notifications WHERE activity_id = :a AND kind = 'reminder'", ['a' => $a]);
ok(($w['ran']['reminders']['reminded'] ?? 0) >= 1 && count($n) === 1 && (int) $n[0]['member_id'] === 26 && str_contains($n[0]['title'], "Remind $x"), 'at its time: one notification for Priya, the subject in the title');
ok(act_row($a)['reminded_at'] !== null && (int) one("SELECT count(*) FROM notification_outbox WHERE record_type = 'activity' AND record_id = :a AND channel = 'email' AND status = 'queued'", ['a' => $a]) === 1, '…reminded_at set; an email queued in the outbox (the default)');
$rl = activity('reminder.deliver', $since);
ok(count($rl) === 1 && $rl[0]['source'] === 'cron' && json_decode($rl[0]['after'], true)['reminded'] >= 1, 'reminder.deliver logged once with the count');
worker_at('reminders', gmdate(DATE_ATOM, strtotime('+35 minutes')));
ok((int) one("SELECT count(*) FROM notifications WHERE activity_id = :a AND kind = 'reminder'", ['a' => $a]) === 1, 'a second pass: not again');
echo "2. Snooze\n";
ok(post_as(26, '/activities/snooze.php', ['activity' => $a, 'until' => '10m'])['code'] === 200, 'activity_snooze 10m');
$r = act_row($a);
ok($r['reminded_at'] === null && $r['snoozed_until'] !== null && abs(strtotime($r['snoozed_until']) - strtotime('+10 minutes')) < 60, '…snoozed_until in ten minutes, reminded_at cleared');
worker_at('reminders', gmdate(DATE_ATOM, strtotime('+5 minutes')));
ok((int) one("SELECT count(*) FROM notifications WHERE activity_id = :a AND kind = 'reminder'", ['a' => $a]) === 1, 'five minutes on: still snoozed');
worker_at('reminders', gmdate(DATE_ATOM, strtotime('+11 minutes')));
ok((int) one("SELECT count(*) FROM notifications WHERE activity_id = :a AND kind = 'reminder'", ['a' => $a]) === 2 && act_row($a)['snoozed_until'] === null, 'after the snooze: delivered again');
post_as(26, '/activities/snooze.php', ['activity' => $a, 'until' => 'tomorrow']);
ok(str_ends_with(substr(act_row($a)['snoozed_until'], 0, 16), '09:00') && substr(act_row($a)['snoozed_until'], 0, 10) === gmdate('Y-m-d', strtotime('+1 day')), 'tomorrow: 09:00 in the owner\'s zone');
ok(field_of(post_as(26, '/activities/snooze.php', ['activity' => $a, 'until' => at('-1 hour')])) === 'until' && field_of(post_as(26, '/activities/snooze.php', ['activity' => $a, 'until' => 'later'])) === 'until', 'a time behind, or no time: refused');
ok(post_as(30, '/activities/snooze.php', ['activity' => $a, 'until' => '1h'])['code'] === 403, 'another Rep may not snooze Priya\'s');
ok(count(activity('activity.snooze', $since)) === 2, 'activity.snooze logged');
echo "3. Done never reminds; the reminder moves with the time\n";
$b = act_id(26, ['kind' => 'task', 'subject' => "Done first $x", 'deal' => $d, 'due_at' => at('+20 minutes')]);
post_as(26, '/activities/complete.php', ['activity' => $b]);
worker_at('reminders', gmdate(DATE_ATOM, strtotime('+1 hour')));
ok((int) one("SELECT count(*) FROM notifications WHERE activity_id = :a", ['a' => $b]) === 0, 'done before its reminder: never reminded');
$c = act_id(26, ['kind' => 'task', 'subject' => "Moved $x", 'deal' => $d, 'due_at' => at('+20 minutes')]);
worker_at('reminders', gmdate(DATE_ATOM, strtotime('+1 hour')));
ok(act_row($c)['reminded_at'] !== null, 'a reminder delivered…');
post_as(26, "/activities/$c/reschedule", ['at' => at('+2 days 10:00')]);
ok(act_row($c)['reminded_at'] === null && str_starts_with(act_row($c)['remind_at'], gmdate('Y-m-d', strtotime('+2 days')) . ' 09:30'), '…rescheduled: armed again, 30 minutes before the new time');
$del = act_id(26, ['kind' => 'task', 'subject' => "Deleted $x", 'deal' => $d, 'due_at' => at('+20 minutes')]);
post_as(26, '/records/delete.php', ['kind' => 'activity', 'record' => $del]);
worker_at('reminders', gmdate(DATE_ATOM, strtotime('+1 hour')));
ok((int) one("SELECT count(*) FROM notifications WHERE activity_id = :a", ['a' => $del]) === 0, 'a deleted one never reminds');
echo "4. A text when asked; an agent's reminder\n";
pg_run("INSERT INTO notification_prefs (member_id, text_enabled, text_kinds) VALUES (26, true, '{reminder}') ON CONFLICT (member_id) DO UPDATE SET text_enabled = true, text_kinds = '{reminder}'");
$t = act_id(26, ['kind' => 'call', 'subject' => "Texted $x", 'deal' => $d, 'starts_at' => at('+40 minutes')]);
worker_at('reminders', gmdate(DATE_ATOM, strtotime('+15 minutes')));
ok((int) one("SELECT count(*) FROM notification_outbox WHERE record_id = :a AND record_type = 'activity' AND channel = 'text'", ['a' => $t]) === 1, 'texts on for reminders: a text queued as well (the kernel sends it, slice 8)');
pg_run("UPDATE notification_prefs SET text_enabled = false WHERE member_id = 26");
$g = act_id(26, ['kind' => 'task', 'subject' => "For the agent $x", 'deal' => $d, 'due_at' => at('+40 minutes'), 'owner' => 40]);
$w = worker_at('reminders', gmdate(DATE_ATOM, strtotime('+15 minutes')));
$dis = q("SELECT * FROM agent_dispatches WHERE record_type = 'activity' AND record_id = :a", ['a' => $g]);
ok(count($dis) === 1 && $dis[0]['kind'] === 'reminder' && (int) $dis[0]['agent_member_id'] === 40 && (int) $dis[0]['deal_id'] === $d && (int) $dis[0]['acting_member_id'] === 26 && ($w['ran']['reminders']['dispatched'] ?? 0) >= 1,
    'an agent\'s reminder: an agent_dispatches row of kind reminder (the dispatches pass sends the turn)');
ok((int) one('SELECT count(*) FROM notifications WHERE activity_id = :a', ['a' => $g]) === 0 && act_row($g)['reminded_at'] !== null, '…no bell row; reminded_at set, so once');
echo "5. Recurring tasks\n";
$rt = act_id(26, ['kind' => 'task', 'subject' => "Weekly report $x", 'due_at' => at('-1 day 09:00'), 'recurrence' => 'FREQ=WEEKLY']);
$w = worker_at('recurring_tasks');
ok((int) one('SELECT count(*) FROM activities WHERE recurrence_parent_id = :a', ['a' => $rt]) === 0, 'an open recurring task is not expanded');
post_as(26, '/activities/complete.php', ['activity' => $rt]);
$since = last_activity_id();
$w = worker_at('recurring_tasks');
$kid = q('SELECT * FROM activities WHERE recurrence_parent_id = :a', ['a' => $rt]);
ok(count($kid) === 1 && $kid[0]['done_at'] === null && str_starts_with($kid[0]['due_at'], gmdate('Y-m-d', strtotime('+6 days')) . ' 09:00') && $kid[0]['recurrence'] === 'FREQ=WEEKLY' && $kid[0]['source'] === 'cron' && (int) $kid[0]['owner_member_id'] === 26,
    'done: the next occurrence a week after the last, at 09:00, Priya\'s, repeating');
ok(count(activity('task.recur', $since)) === 1 && (int) json_decode(activity('task.recur', $since)[0]['after'], true)['from_activity_id'] === $rt, 'task.recur logged from the done one');
worker_at('recurring_tasks');
ok((int) one('SELECT count(*) FROM activities WHERE recurrence_parent_id = :a', ['a' => $rt]) === 1, 'a second pass: one occurrence, never two');
$old = act_id(26, ['kind' => 'task', 'subject' => "Daily $x", 'due_at' => at('-10 days 08:00'), 'recurrence' => 'FREQ=DAILY', 'remind_minutes_before' => 'none']);
post_as(26, '/activities/complete.php', ['activity' => $old]);
worker_at('recurring_tasks');
$k2 = q('SELECT * FROM activities WHERE recurrence_parent_id = :a', ['a' => $old])[0] ?? [];
ok(($k2['due_at'] ?? '') > gmdate('Y-m-d H:i') && array_key_exists('remind_minutes_before', $k2) && $k2['remind_minutes_before'] === null, 'one ten days behind: the next occurrence ahead of now, never in the past; still no reminder');
echo "6. The next step mended\n";
$d2 = deal_make(26);
$s = act_id(26, ['kind' => 'call', 'subject' => "Mend $x", 'deal' => $d2, 'starts_at' => at('+2 days')]);
pg_run("UPDATE deals SET next_activity_id = NULL, next_activity_at = NULL WHERE id = $d2");
$w = worker_at('next_step_flags');
ok(($w['ran']['next_step_flags']['refreshed'] ?? 0) >= 1 && (int) one('SELECT next_activity_id FROM deals WHERE id = :d', ['d' => $d2]) === $s, 'a deal whose stored next step went wrong: mended by the pass');
$w = worker_at('next_step_flags');
ok(($w['ran']['next_step_flags']['refreshed'] ?? -1) === 0, 'nothing wrong: nothing touched');
finish();
